#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';

const payload={"package.json":"","README.md":"","RELEASE_NOTES.md":"","RELEASE_NOTES_0.24.md":"","README_NASADENIE_0.24.txt":"","src/App.tsx":"","src/types.ts":"","src/lib/storage.ts":"","src/data/seed.json":"","src/data/supplierRegistry.ts":"","src/lib/supplierDirectory.ts":"","src/views/OperationsIntelligence.tsx":"","src/views/Suppliers.tsx":"","src/views/Suppliers.css":""};
const target=process.cwd();
const stamp=new Date().toISOString().replace(/[:.]/g,'-');
const backup=path.join(target,`backup-before-v0240-${stamp}`);
function fail(message){console.error('ERROR:',message);process.exit(1)}
let pkg={};
try{pkg=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'))}catch{fail('package.json sa nepodarilo nacitat. Spusti installer v koreni projektu.')}
if(pkg.name!=='is-riadenie-odboru') fail('Tento priecinok nevyzera ako projekt is-riadenie-odboru.');
console.log('IS Riadenie odboru - upgrade na v0.24.0');
console.log('Aktualna verzia:',pkg.version||'nezistena');
if(pkg.version && pkg.version!=='0.23.0') console.log('UPOZORNENIE: installer bol otestovany primarne pre upgrade z v0.23.0.');
fs.mkdirSync(backup,{recursive:true});
let written=0,backed=0;
for(const [rel,encoded] of Object.entries(payload)){
  const destination=path.join(target,rel);
  if(fs.existsSync(destination)){
    const backupPath=path.join(backup,rel);
    fs.mkdirSync(path.dirname(backupPath),{recursive:true});
    fs.copyFileSync(destination,backupPath);backed++;
  }
  fs.mkdirSync(path.dirname(destination),{recursive:true});
  fs.writeFileSync(destination,zlib.gunzipSync(Buffer.from(encoded,'base64')));written++;
  console.log('WRITE',rel);
}
for(const cache of ['dist','.vite',path.join('node_modules','.vite')]){const full=path.join(target,cache);if(fs.existsSync(full)){fs.rmSync(full,{recursive:true,force:true});console.log('CLEAR',cache)}}
const installed=JSON.parse(fs.readFileSync(path.join(target,'package.json'),'utf8'));
if(installed.version!=='0.24.0') fail('Kontrola verzie zlyhala.');
const app=fs.readFileSync(path.join(target,'src/App.tsx'),'utf8');
const suppliers=fs.readFileSync(path.join(target,'src/views/Suppliers.tsx'),'utf8');
const registry=fs.readFileSync(path.join(target,'src/data/supplierRegistry.ts'),'utf8');
const intelligence=fs.readFileSync(path.join(target,'src/views/OperationsIntelligence.tsx'),'utf8');
if(!app.includes("view==='suppliers'")||!app.includes("role==='admin'")) fail('Register dodavatelov nie je korektne zapojeny do App.tsx.');
if(!suppliers.includes('Dodávatelia a zmluvné väzby')||!suppliers.includes('Read-only register')) fail('Supplier UI sa nepodarilo overit.');
if(!registry.includes("'35728531'")||!registry.includes('InterWay, a. s.')) fail('Mapovanie InterWay podla ICO chyba.');
if(!intelligence.includes('resolveSupplierName')) fail('Riadiace centrum nepouziva spolocne pomenovanie dodavatelov.');
console.log('');
console.log(`VERIFIED: v0.24.0 nainstalovana. Suborov zapisanych: ${written}, zalohovanych: ${backed}.`);
console.log('Zaloha:',backup);
console.log('Novy Supabase SQL sa pre tento release nespusta.');
console.log('Nasledne spusti npm run build alebo bezny Vercel deployment.');
